import{_ as o}from"./chunks/67ec30071460f5504928.EfneRsCu.js";import{_ as a,C as l,o as r,c as i,j as e,a as m,E as n,a6 as s}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"如何在拥有多重兴趣的情况下蓬勃发展","description":"","frontmatter":{"title":"如何在拥有多重兴趣的情况下蓬勃发展","originalTitle":"How To Thrive With Multiple Interests","date":"2025-02-15","originalUrl":"https://thedankoe.com/letters/how-to-thrive-with-multiple-interests/","minutes":17,"sourceHash":"b68df7911a38b964f0c3cef2f98affb520b46bfd4dd66defdc669744289cc7cf","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-thrive-with-multiple-interests/"}]]},"headers":[],"relativePath":"letters/how-to-thrive-with-multiple-interests.md","filePath":"letters/how-to-thrive-with-multiple-interests.md"}'),h={name:"letters/how-to-thrive-with-multiple-interests.md"};function u(c,p,d,q,f,b){const t=l("ArticleMeta");return r(),i("div",null,[p[0]||(p[0]=e("h1",{id:"如何在拥有多重兴趣的情况下蓬勃发展",tabindex:"-1"},[m("如何在拥有多重兴趣的情况下蓬勃发展 "),e("a",{class:"header-anchor",href:"#如何在拥有多重兴趣的情况下蓬勃发展","aria-label":'Permalink to "如何在拥有多重兴趣的情况下蓬勃发展"'},"​")],-1)),n(t),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/WZeLFMQOtZ4?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>在我们开始之前先做个小小的公告。</p><p>由于大量的请求,下一期作家训练营（Writer’s Bootcamp）将于3月4日开始。</p><p>最初,我们打算等Kortex AI功能上线后再开启下一期,但我们决定在这期训练营进行期间,针对那些等到功能上线后加入的人另外增加通话（你还能终身获得所有课程更新）。</p><p>所以,如果你想创造属于自己的细分领域,写下你的兴趣,并借此打造一群受众,以此在未来自我保值,那就看看过往学员的成果,并<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">在早鸟价还未结束时报名。</a></p><p>–––</p><blockquote><p>传统教育和过度专业化是一种让人们臣服于主流范式/体系的方式。要学习自然界的普遍原理,做一个深度的通才。</p><p>丹尼尔·施马赫滕伯格（Daniel Schmachtenberger）</p></blockquote><p>认为你应该在18岁就知道自己一生要做什么,这简直是疯了。</p><p>你想学什么。</p><p>你想从事什么职业。</p><p>你的人生最终会走向何处。</p><p>大多数时候,答案就是——活成你父母的样子。</p><p>一份工作。一个配偶。一份房贷。几次假期。几次不错的晚餐。也许养只猫或狗。也许生几个孩子？</p><p>也许不会……你知道的……经济状况之类的问题。</p><p>至少这是你被期望要做的事。</p><p>这是社会对你的期望。</p><p>但你<em>不一样</em>。</p><p>你有多重兴趣。</p><p>只专注于一件事,是你存在的痛苦之源。</p><p>你控制不住自己。你想探索生活所能提供的一切。你想拥抱人类经验的全部广度。</p><p>但无论你转向哪里,父母、老师、甚至朋友,都会在你试图走自己的路时,把你打压下去。</p><p>他们说你有“闪光物体综合症”，仿佛这是件坏事。</p><p>他们对你的梦想和志向暗中冷嘲热讽（因为他们想“为你着想”,但前提是不能比他们做得更好）。</p><p>他们希望你走“安全”的路线。当医生。当律师。做点体面的事。拿个高薪学位。</p><p>他们把你的思想硬塞进他们能理解的那个小盒子里,而你<em>恨极了</em>这一点。</p><p>他们不知道,在这个新的工作未来里,拥有多重兴趣其实是一种超能力。</p><p>曾经被视为“安全”的路线,现在其实是最不安全的那条。</p><h2 id="三大差异化要素——能动性、品味与通才性" tabindex="-1">三大差异化要素——能动性、品味与通才性 <a class="header-anchor" href="#三大差异化要素——能动性、品味与通才性" aria-label="Permalink to &quot;三大差异化要素——能动性、品味与通才性&quot;">​</a></h2><blockquote><p>一个人应该能够换尿布、策划一场入侵、屠宰一头猪、掌舵一艘船、设计一座建筑、写一首十四行诗、平衡账目、砌一面墙、接一根骨头、安慰临终之人、听从命令、发出命令、合作共事、独立行动、解方程、分析新问题、铲粪、编程、烧一顿美味的饭、有效地战斗、英勇地死去。专业化只属于昆虫。</p><p>罗伯特·A·海因莱因（Robert A. Heinlein）</p></blockquote><p>在19世纪初中期,当美国正在工业化并需要教育大量移民儿童时,像霍拉斯·曼（Horace Mann）这样的教育者前往普鲁士研究他们的体系。</p><p>这套普鲁士教育体系,设计初衷就是培养顺从的士兵、听话的公民、公职人员和守规矩的工人。</p><p>它通过以下方式来实现这一点：</p><ul><li>强制出勤</li><li>教师培训</li><li>全国统一课程与学生测试</li><li>按年龄划分学生</li><li>年级制度的概念</li></ul><p>如果你和我有点像,那么读到这里,你心里某个小部分已经死了。</p><p><em>学生被教导的是如何工作,而不是如何思考。</em></p><p>曼和其他人对这种体系的效率和标准化印象深刻,于是将其中许多方法引入了美国学校,尤其是在马萨诸塞州,这后来成为其他州效仿的模板。</p><p>由于你并不是这个教育体系的资金来源,你也无法掌控<em>教什么内容</em>。</p><p>你被要求读这个、背那个,如果你不这样做,你那工业时代思维的父母就会责骂你,并威胁要禁足你（这样你就无法和朋友交流,也无法追求兴趣爱好）。</p><p>更进一步说,标准化教育必须偏向最底层的五分之一学生。</p><p>换句话说,你被迫以公立教育体系中最笨的那20%人的速度来学习。</p><p>这极具破坏性。</p><p>因为如果你理解大脑的运作方式,你就会明白,你只会吸收那些与你思维所设定目标相符的信息。</p><p>而如果你的目标只是拿个学位、找份工作,那你的命运就是变得可被替代,因为你没有学到那些能让人获得自由的多重兴趣。</p><p>重点就在这里：</p><p>社会希望你成为专才,因为有用的劳动者才能为社会服务。</p><p>但你所敬佩的每一个人,<em>都不是</em>专才。专才是工具。工具会被淘汰。而AI正在做这件淘汰的事。</p><p>每一个自由且成功的人,都是通才。是博学者。他们明白,要实现宏大的愿景,就必须在那些尚未被定义的生活领域中,学习并做许多不同的事情。</p><p>但通才性只是方程式中的一部分。</p><p>我们正经历着第二次文艺复兴。</p><p>我们的口袋里装着爱因斯坦和达·芬奇的力量。</p><p>个人——而非机构——比以往任何时候都更有能力凭借多重兴趣而蓬勃发展。</p><p>但即便如此,人们还是什么都没做。</p><p>这不是因为他们懒惰。</p><p>这不是因为他们缺乏创造力。</p><p>这是因为他们的思维已被一个从他们的愚昧中获益的社会,编程了20多年。</p><p>在未来的工作世界里,你需要彻底改变对自己未来的思考方式。</p><p>通才性是必备的,现在我们来谈谈<em>品味</em>。</p><h3 id="如何培养品味" tabindex="-1">如何培养品味 <a class="header-anchor" href="#如何培养品味" aria-label="Permalink to &quot;如何培养品味&quot;">​</a></h3><p>我原本打算总结这段话,但我不想糟菫它的原意：</p><blockquote><p>没人会告诉初学者这一点,我真希望有人当初告诉过我。我们这些从事创意工作的人,之所以入行,是因为我们有好的品味。但存在一个差距。头几年你做出来的东西,并不算好。它试图变好,它有潜力,但还不行。可你的品味——那个让你入这行的东西——依然锐利如刀。而正是你的品味,让你的作品让你自己失望。很多人从没走出过这个阶段,他们放弃了。我认识的那些做出有趣、创意作品的人,几乎都经历过这几年的煎熬。我们都知道自己的作品还没有我们想要的那种特质。我们都经历过这个阶段。如果你刚起步,或者仍处于这个阶段,你要知道,这很正常,而你能做的最重要的事,就是大量地去做。给自己定一个期限,让自己每周完成一个故事。只有通过大量的创作,你才能填补那个差距,让你的作品配得上你的野心。而我花了比我认识的任何人都更长的时间才弄明白这一点。这需要一段时间。花些时间是正常的。你只需要拼尽全力去闯过去。</p><p>艾拉·格拉斯（Ira Glass）</p></blockquote><p>让我试着把这个说清楚。</p><p>跟着我,仔细读：</p><p>智力已经不再是一种差异化资源。</p><p>AI模型不断变得越来越强,而这些模型的价格却越来越接近于零。</p><p>每个人都拥有他们所需要的一切答案（然而99%的人却没有意识到或没有利用它……因为智力在孤立状态下已被证明是一种糟糕的资源。成功的故事远不止于此）。</p><p>这就是事情变得棘手的地方。</p><p>AI正在取代专才角色,因为可预测的输入会带来可预测的输出。</p><p>由于许多工作只是一系列重复性任务,产出的是非创造性的结果,AI足以胜任。</p><p>但当你加入另一层抽象,或者多层抽象时,可能出现的结果数量就变成无限的了。AI只会给你<em>一个</em>结果,除非你去打磨它,或者让AI自我打磨。问题是,那可能并不是最好的结果。<strong>而且它绝对不是那个能赢得消费该内容的支持者们的喜爱与关注的结果。</strong></p><p>大多数人生成的大多数AI内容,都是垂圾。<a href="/letters/ai-will-end-the-internet">死气沉沉的互联网</a>正被没人关心的垂圾内容填满。</p><p>举个例子,假设你想写一本书。</p><p>你也可以把它想成开发一款软件、设计一个网站,或任何其他真正的创意工作。</p><p>现在,你可以用几个精心撰写的提示词,让AI写出一本关于“如何专注”还算不错的书。</p><ul><li>打开Claude Sonnet 3.5</li><li>赋予它一个目的（代笔人）</li><li>给它你的写作风格、语气和声音</li><li>给它目标受众</li><li>让它根据该受众的痛点创建目录</li><li>对每一章,让它包含一个相关的故事、一个核心洞见、可执行的步骤,以及一个新颖的概念,比如“时间块（Time Blocking）”</li><li>给它你之前写过关于专注的想法</li><li>为每一章创建并打磨大纲</li><li>完成这本书,并按照你的喜好打磨它</li></ul><p>现在,找1000个真实的人（无论是否使用AI）,让他们就同一主题写一本书。</p><p><em>每一个最终成果都会彼此不同。</em></p><p>一本书可以用1000种不同的方式写出来。</p><p>而1000个不同的人,也能对那本书做出1000种不同的<em>解读</em>。</p><p>重点在于：</p><p>AI能否写出一本书、开发一款软件、设计一个网站、写一百万条社交媒体帖子,这都不重要。</p><p>为什么？因为那不是让创意工作成功的关键。</p><p>那也不是让人们<em>关心你的创意作品</em>的关键。</p><p>用AI写你想写的所有书。看看它能带你走多远。大多数人喜欢喋喋不休地谈论AI将如何取代一切,把这当作一个不去为自己的人生做任何事的借口——就像他们一生中抓住任何能抓住的借口一样。</p><p>行动者去行动。大多数人不会。我们接下来会谈到这一点。</p><p>眼下,要意识到多重兴趣与<em>品味</em>是融合在一起的。</p><p>任何人都能创造任何东西。如果他们愿意,他们可以拥抱自己作为通才的本性。</p><p>但真正定义一本书、一个品牌、一款软件以及任何其他创意作品的,不是创造那个东西的<em>能力</em>,而是<em>你以一种除了你之外没人能想到的方式,跨越各个学科去综合各种观念的能力。</em></p><p>一本关于“<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">如何专注</a>”的书,如果你把哲学、心理学、玄学和灵性的概念融入其中,而不只是心理自助的套路,它就会呈现出一种全新的形态。</p><p>由于大多数人的品味已经被学校和工作磨钝了,你占据着巨大的优势,因为你没有让这些阻止你去学习那些超出既定范围的东西。你热爱探索未知。</p><p>入门级别将会灭绝,因为初学者有品味,但无法将其变为现实。正如格拉斯在上面那段话中指出的,他们还没有经历过足够多的练习和失败。</p><p>在未来的工作世界里,高薪的工作将只留给高技能人才——那些能做很多事、并拥有已习得的品味的人。</p><p>但坦白说,大多数人不会得到那些工作。</p><p>这些机会将会寥寥无几。</p><p>就像进入NBA一样,只留给那0.1%的精英。</p><p>一个白日梦。</p><p>所以,如果你拥有多重兴趣,又有品味,那还差拼图的最后一块。</p><h3 id="能动性-受雇-vs-创业" tabindex="-1">能动性：受雇 VS 创业 <a class="header-anchor" href="#能动性-受雇-vs-创业" aria-label="Permalink to &quot;能动性：受雇 VS 创业&quot;">​</a></h3><p>令人悲哀的是,“生意”和“创业”竟然成了脏话。</p><p>对大多数人来说,当他们听到这些时,脑海中会瞬间涌起怀疑和警觉:</p><ul><li>&quot;那需要很多钱才能开始。&quot;</li><li>&quot;我没那个天赋去做那件事。&quot;</li><li>&quot;向别人收钱?听起来像是骗局。&quot;</li><li>&quot;我不知道怎么注册LLC或者报税,所以我永远学不会。听起来太无聊了。&quot;</li></ul><p>我在这里不是要谈论作为一种角色、一个头衔,或者只属于有天赋的人的&quot;创业&quot;。</p><p>我在这里要谈的是它真正的本质:</p><p><em>一种心态。</em></p><p>员工和创业者之间的区别,就是低能动性和高能动性之间的区别。在这个语境下,<em>高能动性的人是那些自己制定目标并主动追求,不需要别人许可的人。</em>低能动性的人则是那些被分配目标、去追求它们,只是因为他们的思维方式让他们看不到任何其他选项的人。真正的能动性只能在你为每一个问题都自我归责——即便错不在你——的时候才能培养出来。</p><p>创业者常常也是员工,但员工很少是创业者。</p><p>在顶尖公司里,最受追捧的员工是那些不需要许可就能解决问题的人。他们只是<em>去做。</em>他们有能动性。他们不需要被人牵着手才能创造价值。</p><p>但再说一次,未来的工作岗位将只留给精英。</p><p>所以在我看来,对于那些有高远志向、又有多种兴趣的人来说,主要的出路就是<em>打造自己的道路,</em>而做到这一点的唯一方式就是成为创业者(无论你的梦想需要多长时间才能扎根)。</p><p><img src="'+o+'" alt=""></p><p>现在,人们很容易把我归类为&quot;所有朝九晚五的工作都是坏的!&quot;的阵营,但那根本不是我的观点。</p><p>不过,我确实对心理学有相当程度的理解。</p><p>作为孩子,生活有一种&quot;魔力&quot;,因为一切都是新的。你不断在进步、演变,迎接让生活值得一过的新挑战。</p><p>学校模拟了这种&quot;狂猎&quot;良好多巴胺的渴望,通过提供一种类似电子游戏的学习进阶体系。</p><p>当你接受第一份工作时,一开始是充满挑战的。你培养技能来治愈自己的焦虑。然后,当你走到那条职业阶梯所能允许的最远处时,挑战和新鲜感便不复存在。你的日子变成了一片重复的模糊。</p><p>这对你的心理是极具破坏性的。</p><p>你被困在已定义的、已知的事物之中。你无法逃脱,因为月薪令人上瘾,而你把生活方式撑到刚好能被那份薪水覆盖的极限。</p><p>对于那些想从生活中获得更多的人来说,唯一的出路就是创业。</p><p>潜入未知。拥抱不确定性。接受那无穷无尽的挑战之链,它会把童年般的魔力——那种高潮与低谷交替的感觉——重新带回你的生活。</p><p>如果你有多种兴趣,那你正处在一个绝佳的位置。</p><h2 id="如何把你的兴趣变成收入" tabindex="-1">如何把你的兴趣变成收入 <a class="header-anchor" href="#如何把你的兴趣变成收入" aria-label="Permalink to &quot;如何把你的兴趣变成收入&quot;">​</a></h2><blockquote><p>我会把重心放在内容创作者这个方向上,因为我相信那是&#39;冰球即将去往的地方&#39;。这是一个更重要的转变……关于我们所有人消费信息方式的转变。</p><p>查马斯·帕里哈皮蒂亚(Chamath Palihapitiya)</p></blockquote><p>最后一个问题是这样的:</p><p>你有多种兴趣。</p><p>你正在培养品味。</p><p>你已经准备好提升自己的能动性。</p><p>但你完全不知道<em>从哪里开始。</em></p><p>如果你还年轻,你唯一知道去看的地方就是招聘网站,或许还有一些自由职业市场平台。</p><p>所以,我不会给你一个单一的去处,因为一条单一的、已知的道路对你没有任何好处,我会引导你去创造自己的道路,把兴趣转化为收入。</p><h3 id="_1-选择一条元路径" tabindex="-1">1) 选择一条元路径 <a class="header-anchor" href="#_1-选择一条元路径" aria-label="Permalink to &quot;1) 选择一条元路径&quot;">​</a></h3><p>你能犯的最大错误就是把自己框死在一个特定的模式里。</p><p>比如开一家能动性(代理)公司,或者做电商生意,或者做一些其他小众模式,比如亚马逊的按需印刷。</p><p>这些都是很好的学习内容,但它们只是用来获取有助于实现你愿景的相关技能。就像一份工作一样。</p><p>更好的做法是往后退一步,去发掘<em>让所有这些模式得以运转的原理。</em></p><p>因为一旦你理解了那些原理,你就能在任何你选择去做的事情上创造成功。</p><p>所以,如果你想做自己的事业,你需要三件东西:</p><ul><li>一个有价值的产品或服务</li><li>一种吸引在乎它的人的方法</li><li>让人们在乎的能力</li></ul><p>多亏了互联网,现在这三者对任何有网络连接的人来说都变得触手可及。</p><p>你可以相对轻松地打造一个产品或服务:</p><ul><li>你可以写一本电子书</li><li>你可以围绕你的兴趣开一门群组式课程</li><li>你可以借助AI辅助的编程和学习来构建软件</li></ul><p>我们在<a href="/letters/the-1-million-product-how-to-package-market-your-knowledge"><em>如何打包并推广你的知识</em></a>这篇通讯中深入讨论过这个话题。</p><p>对于那些不想在打造传统企业上投入过多时间和金钱的初学者来说,这些是最好的选择。</p><p>一旦你推出了几个这样的产品,你现在就有了关于什么行之有效的数据,也有了一些可以用来投资的现金。</p><p>到那个阶段,你可以走贾斯汀·韦尔什(Justin Welsh)的路线,作为一人企业经营一个价值数百万美元的信息产品生意,放松地生活;或者你可以走我的路线,把这些当作起点,去打造另一个需要更多资源的产品,比如<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>。</p><p>这里的问题在于,再说一次,任何人都能打造任何东西。</p><p>但不是每个人都能<em>吸引在乎那件东西的人。</em></p><p>这正是大多数程序员、作家或创意人失败的地方。他们打造了一个很酷的应用,或者写了一本书,或者创作了艺术作品,但他们招不到顾客,于是失败了。</p><p>幸运的是,你现在不再需要付费广告、广告牌,或者上电视访谈节目来为你的生意引流了。</p><p>你只需要开始在网上发布关于你的知识和兴趣的内容。</p><p><em>你要把自己置于受众面前。</em></p><p>你可以选择打造、借用,或者购买一个受众群体。</p><p>既然我们想要的是易获得、负担得起、又具备高杠杆的方式,那么现在你应该把注意力集中在<em>打造</em>一个受众群体上。这在社交媒体上完成,直到社会下一层社交层出现为止。</p><p>&quot;但是Dan,每个人都在变成创作者,谈论的都是同一件事。&quot;</p><p>错了。你正身处一个信息回音室之中。</p><p>成为创作者与具体兴趣无关。只要你能把它讲得有说服力,你就可以谈论任何你想谈的东西。</p><p>你不<em>必</em>谈论自我发展、哲学或商业。你只是以为你必须这样做,因为你和我有相似的兴趣(这就是你读这些文章的原因),所以也许你应该围绕那些兴趣打造受众。不是每个人都有这些兴趣。</p><p>每个人都在变成创作者,因为这就是你作为个体夺回自身主权的方式。世界上有企业,也有消费者。创作者兼具两者。所以是的,这个市场将会绝对庞大,并将构成新经济的很大一部分。</p><p>问题是,这一切都远远谈不上容易。</p><p>你需要正确的技能,既能吸引受众,<em>又</em>能让他们在乎你是谁、你做什么。</p><p>换句话说,你需要一个<em>媒介</em>和一个<em>信息。</em></p><p>写作和演讲就是你的媒介。</p><p>你可以写帖子、话题串、通讯、产品文案、广告、邮件、文章等等。或者你对着镜头说话,把你的信息传递给可能从中受益的人。</p><p>心理学、营销、销售和说服力则帮你塑造信息本身。你需要用一种能够抓住注意力、清晰表达价值、建立信任的方式来写作或演讲。</p><p>如果你想在这方面获得帮助,下一期<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">写作者训练营(Writer&#39;s Bootcamp)</a>将在3月4日开始。它会帮助你打造属于自己的&quot;细分领域中的唯一&quot;,围绕你的兴趣写作,并学会那些能作为你未来&quot;护城河&quot;的技能来打造受众。</p><h3 id="_2-交集就是你的优势" tabindex="-1">2) 交集就是你的优势 <a class="header-anchor" href="#_2-交集就是你的优势" aria-label="Permalink to &quot;2) 交集就是你的优势&quot;">​</a></h3><p>如果每个人都在打造受众,你要怎么脱颖而出?</p><p>嗯,这只在你还不是真实自我的时候才会是个难题。</p><p>如果你是真实的自己,而地球上所有其他人也都是真实的自己,那么每个人都会是独一无二的。</p><p>换句话说,如果每个人都变成了创作者,而这些创作者都是他们真实的自己——意味着他们解决了自己的问题并把解决方案卖出去——那我们就会进入某种数字部落时代。小型的自给自足的部落会形成,其中每个人都能用自己的独特性去帮助这个部落里的其他人。这已经在发生了。</p><p>你不需要很多粉丝。你需要的是几百个支持你的作品、需要你所提供东西的人。而且,随着互联网的运行方式,这几百人每一两个月都会有进有出,让你能够持续维持你所做的事。你在演变,部落也在演变,互联网就是一股不断流动的注意力之流。</p><p>但我们习惯于顺从。我们模仿别人。我们缺乏对自己未来的愿景,也缺乏把它变成现实的能动性。</p><p>以下是我想让你去做的事,以发现你的独特性:</p><ul><li><strong>写下你的故事</strong>——几年前你在哪里?那时你的心态是怎样的?重大的转折点是什么?你学到了什么技能?你现在在哪里?你能帮助别人做到同样的事吗?</li><li><strong>写出10-20个兴趣</strong>——拿出一个笔记本,写下10到20件你喜欢研究、想去研究,或者略有兴趣的事情。</li><li><strong>为每个兴趣写出3个痛点</strong>——在每个兴趣下面,写出3个你自己经历过或别人在这些兴趣相关领域中面临的问题或痛点。</li><li><strong>把这些点连起来</strong>——在你的故事、你的兴趣和这些痛点之间画线连接。你会惊讶于有多少东西彼此相连。</li></ul><p>我的写作是无法被AI复制的(除非是我亲自操作AI),因为我的&quot;优势&quot;在于我的个人经历与哲学、再与商业的结合。</p><p>我可以谈论和其他所有人一样的话题,因为那正是注意力所在的地方,但我的内容之所以脱颖而出,是因为我<em>如何构建</em>它。</p><p>其次,我专注于吸引与我有相似兴趣的人。</p><p>为什么?因为我知道我能在某种程度上帮助他们。</p><p>如果你想做同样的事,就拿出你上面写的东西。</p><p>为你列出的每一个痛点写一篇文章或帖子。</p><p>在你的写作中不断穿插你的个人故事。</p><p>把相互关联的兴趣融入其中,以合成出独特的想法。</p><p>当然,还要坚持不懈。</p><p>记住,你是有品味的,但它不会体现在你的作品里,除非你练习了好几年。</p><p>而且,不,考虑到你花了18年以上的时间被逼着做你不想做的事,几年的时间根本算不上多。几年的努力其实什么都不算。</p><p>你不想全力投入,是因为你觉得&quot;有更好的事情可以做&quot;,而这所谓&quot;更好的事&quot;其实只是用廉价的快感来麻痹痛苦,逃避你现在的处境。</p><p>你唯一应该想做的事就是走出去。</p><h3 id="_3-融合艺术与商业" tabindex="-1">3) 融合艺术与商业 <a class="header-anchor" href="#_3-融合艺术与商业" aria-label="Permalink to &quot;3) 融合艺术与商业&quot;">​</a></h3><blockquote><p>要打造产品,&quot;做人们想要的东西。&quot; &gt; &gt; 要创造艺术,做<em>你自己</em>想要的东西。 &gt; &gt; (最厉害的人两者都做)。</p><p>纳瓦尔·拉维肯特(Naval Ravikant)</p></blockquote><p>令人悲哀的是,大多数人无法接受这样一个事实:商业可以是一件非常有满足感的事。</p><p>幸福是一枚双面的硬币:</p><p>一面是取得进步所需的创造力,另一面是为比自己更宏大的事物做出贡献。</p><p>换句话说,就是变得有价值,并把这份价值分享出去。</p><p>借助互联网,任何人都能做到这一点,并收获这样做所带来的回报。</p><p>当你创造出自己想要的东西,并把它分享给有相似兴趣的人时,你就把艺术和商业融合在了一起,因为他们也很可能想要它。</p><p>为自己而写内容。</p><p>把互联网当作你的公开日记。</p><p>努力让它传播给更多人。</p><p>打造一个你自己会购买、使用并从中受益的产品。</p><p>给自己一些时间,你会做得非常好。</p><p>——丹</p><hr><p><a href="/en/letters/how-to-thrive-with-multiple-interests">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',201))])}const A=a(h,[["render",u]]);export{g as __pageData,A as default};
